package com.securebiz.risk.service;import org.springframework.stereotype.Component;import org.springframework.web.client.*;import java.util.*;
@Component public class AiDetectionClient{private final RestClient client;public AiDetectionClient(RestClient client){this.client=client;}public Prediction predict(UUID snapshot,Map<String,Double>features){var request=new PredictionRequest(snapshot.toString(),"behavior-v1",features);try{return client.post().uri("/predict").body(request).retrieve().body(Prediction.class);}catch(RestClientResponseException e){throw new IllegalStateException("AI detection service rejected prediction: "+e.getStatusCode(),e);}catch(ResourceAccessException e){throw new IllegalStateException("AI detection service is unavailable",e);}}public ModelInfo modelInfo(){try{return client.get().uri("/model/info").retrieve().body(ModelInfo.class);}catch(RestClientException e){return new ModelInfo(false,null,null,null,null);}}record PredictionRequest(String feature_snapshot_id,String feature_schema_version,Map<String,Double>features){}public record Prediction(String feature_snapshot_id,String model_version,double anomaly_score,boolean is_anomaly,double threshold,double latency_ms){}public record ModelInfo(boolean available,String model_version,String algorithm,String feature_schema_version,String loaded_at){}}
